// gemm, fip: the inner-product form (own code; generated by tasks/gemm/reference/gen_fip.py).
//
// sum_j w[j] x[j] = sum_t (w[2t] + x[2t+1]) (w[2t+1] + x[2t]) - sum_t w[2t] w[2t+1] - sum_t x[2t] x[2t+1]:
// a row of the array has E/2 multipliers; the weight term is computed once per loaded tile row by one shared unit
// and kept in the row (double-buffered like the weights), the activation term once per slice, and it travels down
// the rows with the slice. The rest is the classical array's machine.
//
// T = E: a weight tile is E x E, one tile row per memory beat. Per job, in chunks of at most 2 E vectors:
// the chunk's activations are written to the on-chip buffer; then, row block by row block, every tile of the block
// is loaded into the cells' shadow registers (one burst per tile) while the previous tile computes, the chunk's
// vectors stream through the array once per tile, the sums accumulate in the row memories, and after the block's
// last tile the sums are read out through the output stage into the result FIFO.
module gemm #(parameter int LGE = 2, parameter int LAT = 3) (
  input  logic                   clk, rst,
  input  logic                   job_valid,
  input  logic [3:0]             job_lgn,
  input  logic [15:0]            job_batch, job_mul,
  input  logic [5:0]             job_shift,
  input  logic [15:0]            job_zp, job_lo, job_hi,
  input  logic                   rq_ready,
  input  logic                   rd_valid,
  input  logic [16*(1<<LGE)-1:0] rd_data,
  input  logic                   x_valid,
  input  logic [16*(1<<LGE)-1:0] x_data,
  input  logic                   y_ready,
  output logic                   job_ready,
  output logic                   rq_valid,
  output logic [31:0]            rq_addr,
  output logic [23:0]            rq_len,
  output logic                   rd_ready,
  output logic                   x_ready,
  output logic                   y_valid,
  output logic [15:0]            y_vec,
  output logic [4:0]             y_row,
  output logic [16*(1<<LGE)-1:0] y_data
);
  localparam int E = 1 << LGE;
  localparam int MEMW = 16 * E;
  localparam int LGB = (LGE > 4) ? LGE - 4 : 0;      // log2 of the buffer's banks of 1024 beats
  localparam int VW = LGE + 1;                       // a vector index inside a chunk (2 E vectors)
  localparam int DL = E / 2 + 3;                      // from a buffer read to row 0's accumulator read
  localparam int DRAIN = 3 * (E / 2) + 5;              // from a block's last buffer read to its read-out
  localparam int SW = 33 + LGE;                      // the sums inside the array, modulo 2^SW
  localparam int TS = LGE / 2;                       // the register stages of a correction's adder tree
  localparam int CAP = 16;                           // result beats under way at most (the FIFO's size)

  // ---- the job
  logic [2:0]  lgq;                                  // log2 (N / E)
  logic [4:0]  nbm;                                  // N / E - 1
  logic [15:0] rem, vbase;
  logic [15:0] mul, zp, lo, hi;
  logic [5:0]  shift;
  logic [VW:0] cnt;                                  // vectors in this chunk, 1 .. 2 E

  // ---- the main sequence
  typedef enum logic [2:0] {M_IDLE, M_INGEST, M_TILE, M_RUN, M_DRAIN, M_RO, M_FLUSH} mstate_t;
  mstate_t     ms;
  logic [VW:0] iv;                                   // ingest: vector
  logic [4:0]  ic;                                   // ingest: beat of the vector
  logic [4:0]  rr, cc;                               // the tile: row block, column block
  logic [VW:0] rv;                                   // the vector being read
  logic [15:0] dcnt;                                 // drain counter

  // ---- registers that drive the children
  logic            swap;
  logic            xb_rd;
  logic [LGE+5:0]  xb_ra;
  logic [E-1:0]    ld;
  logic [MEMW-1:0] wbeat;
  logic [DL*(VW+2)-1:0] actl;                        // the accumulate control on its way to row 0
  logic            r_rd;
  logic [VW-1:0]   r_v;
  logic [20:0]     r_tag;                            // the position (vector, row block) of the beat being read out
  logic [5:0]      t_valid;                          // read-out pipeline: valid, and the beat's position
  logic [6*21-1:0] t_tag;
  logic [4:0]      occ;                              // result beats issued and not yet transferred

  // ---- the weight loader
  typedef enum logic [1:0] {L_IDLE, L_REQ, L_RX} lstate_t;
  lstate_t     ls;
  logic [10:0] tiles;                                // tiles of this chunk not yet requested
  logic [4:0]  lr, lc;
  logic [LGE:0] li;
  logic        sh_full;
  logic [15:0] wave;                                 // cycles until the last swap has passed every cell

  logic [MEMW*(1<<LGB)-1:0] xq;
  logic [LGB:0]    xqsel;
  logic [E/2-1:0]  sk_swap;
  logic [SW-1:0]   sk_cx, cw_d;
  logic [E*(TS+1)-1:0] ldd;                          // the load strobes, delayed as the weight correction is
  logic [MEMW-1:0] sk_x, ya;
  logic            f_valid;
  logic [MEMW+20:0] f_dout;

  gemm_xbuf #(.LGE(LGE), .LGB(LGB)) xbuf (
    .clk(clk), .we_v(x_valid), .we_r(x_ready), .waddr({iv[VW-1:0], ic}), .wdata(x_data),
    .rd(xb_rd), .raddr(xb_ra), .q(xq), .qsel(xqsel));
  gemm_skewp #(.LGE(LGE), .LGB(LGB)) skew (
    .clk(clk), .swap(swap), .q(xq), .qsel(xqsel), .swap_o(sk_swap), .x_o(sk_x), .cx(sk_cx));
  gemm_wcorr #(.LGE(LGE)) wcorr (.clk(clk), .w(wbeat), .ncw(cw_d));
  gemm_arrayf #(.LGE(LGE)) array (
    .clk(clk), .ld(ld), .w_d(wbeat), .cld(ldd[E*TS +: E]), .cw_d(cw_d), .swap(sk_swap), .x(sk_x), .cx(sk_cx),
    .a_rd(actl[DL*(VW+2)-1]), .a_first(actl[DL*(VW+2)-2]), .a_v(actl[DL*(VW+2)-3 -: VW]),
    .r_rd(r_rd), .r_v(r_v), .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi), .y(ya));
  gemm_fifo #(.W(MEMW + 21), .LGD(4)) fifo (
    .clk(clk), .rst(rst), .push(t_valid[5]), .din({t_tag[5*21 +: 21], ya}), .pop_ready(y_ready),
    .valid(f_valid), .dout(f_dout));
  assign y_valid = f_valid;
  assign y_data  = f_dout[MEMW-1:0];
  assign y_row   = f_dout[MEMW +: 5];
  assign y_vec   = f_dout[MEMW+5 +: 16];

  logic        x_take, y_take, start_pass, ro_go, rd_take;
  logic [VW:0] cnt_n;
  assign x_take     = x_valid & x_ready;
  assign y_take     = y_valid & y_ready;
  assign rd_take    = rd_valid & rd_ready;
  assign start_pass = (ms == M_TILE) & sh_full & ~xb_rd;   // one idle cycle between passes (the row memories)
  assign ro_go      = (ms == M_RO) & (occ < CAP[4:0]);
  assign cnt_n      = (rem > 16'(2 * E)) ? (VW+1)'(2 * E) : rem[VW:0];

  always_ff @(posedge clk) begin
    // the accumulate control's delay line and the read-out pipeline
    actl    <= {actl[(DL-1)*(VW+2)-1:0], ((ms == M_RUN) | start_pass), (cc == 5'd0), (start_pass ? VW'(0) : rv[VW-1:0])};
    t_valid <= {t_valid[4:0], r_rd};
    t_tag   <= {t_tag[5*21-1:0], r_tag};
    if (rd_take) wbeat <= rd_data;
    ldd <= rst ? '0 : (E*(TS+1))'({ldd, ld});

    if (rst) begin
      ms        <= M_IDLE;
      job_ready <= 1'b0;
      x_ready   <= 1'b0;
      swap      <= 1'b0;
      xb_rd     <= 1'b0;
      r_rd      <= 1'b0;
      t_valid   <= 6'd0;
      occ       <= 5'd0;
      ls        <= L_IDLE;
      rq_valid  <= 1'b0;
      rd_ready  <= 1'b0;
      ld        <= '0;
      tiles     <= 11'd0;
      sh_full   <= 1'b0;
      wave      <= 16'd0;
      rq_addr   <= 32'd0;
      rq_len    <= 24'd0;
    end else begin
      swap  <= 1'b0;
      xb_rd <= 1'b0;
      r_rd  <= 1'b0;
      occ   <= occ + {4'd0, ro_go} - {4'd0, y_take};
      if (wave != 16'd0) wave <= wave - 16'd1;

      case (ms)
        M_IDLE: begin
          if (job_valid & job_ready) begin
            job_ready <= 1'b0;
            lgq   <= 3'(job_lgn - 4'(LGE));
            nbm   <= 5'((6'd1 << 3'(job_lgn - 4'(LGE))) - 6'd1);
            rem   <= job_batch;
            vbase <= 16'd0;
            mul   <= job_mul;
            shift <= job_shift;
            zp    <= job_zp;
            lo    <= job_lo;
            hi    <= job_hi;
            ms    <= M_INGEST;
            x_ready <= 1'b1;
            iv    <= '0;
            ic    <= 5'd0;
            cnt   <= (job_batch > 16'(2 * E)) ? (VW+1)'(2 * E) : job_batch[VW:0];
            tiles <= 11'((12'd1 << 3'(job_lgn - 4'(LGE))) << 3'(job_lgn - 4'(LGE)));
            lr    <= 5'd0;
            lc    <= 5'd0;
          end else
            job_ready <= 1'b1;
        end
        M_INGEST: begin
          if (x_take) begin
            if (ic == nbm) begin
              ic <= 5'd0;
              iv <= iv + 1'b1;
              if (iv + 1'b1 == cnt) begin
                x_ready <= 1'b0;
                ms <= M_TILE;
                rr <= 5'd0;
                cc <= 5'd0;
              end
            end else
              ic <= ic + 5'd1;
          end
        end
        M_TILE: begin
          if (start_pass) begin                      // the tile is in the shadow registers: start its pass
            swap    <= 1'b1;
            sh_full <= 1'b0;
            wave    <= 16'(E / 2 - 1);
            xb_rd   <= 1'b1;
            xb_ra   <= {VW'(0), cc};
            rv      <= (VW+1)'(1);
            ms      <= (cnt == (VW+1)'(1)) ? ((cc == nbm) ? M_DRAIN : M_TILE) : M_RUN;
            if (cnt == (VW+1)'(1)) cc <= (cc == nbm) ? 5'd0 : cc + 5'd1;
            dcnt    <= 16'(DRAIN);
          end
        end
        M_RUN: begin
          xb_rd <= 1'b1;
          xb_ra <= {rv[VW-1:0], cc};
          rv    <= rv + 1'b1;
          dcnt  <= 16'(DRAIN);
          if (rv + 1'b1 == cnt) begin
            cc <= (cc == nbm) ? 5'd0 : cc + 5'd1;
            ms <= (cc == nbm) ? M_DRAIN : M_TILE;
          end
        end
        M_DRAIN: begin                               // the block's last sums are on their way to the row memories
          dcnt <= dcnt - 16'd1;
          rv   <= '0;
          if (dcnt == 16'd0) ms <= M_RO;
        end
        M_RO: begin
          if (ro_go) begin
            r_rd  <= 1'b1;
            r_v   <= rv[VW-1:0];
            r_tag <= {vbase + 16'(rv), rr};
            rv   <= rv + 1'b1;
            if (rv + 1'b1 == cnt) begin
              if (rr == nbm) ms <= M_FLUSH;
              else begin
                rr <= rr + 5'd1;
                ms <= M_TILE;
              end
            end
          end
        end
        M_FLUSH: begin                               // the chunk's last results leave the output stage
          if (~r_rd & (t_valid == 6'd0)) begin
            vbase <= vbase + 16'(cnt);
            rem   <= rem - 16'(cnt);
            if (rem == 16'(cnt)) begin
              ms <= M_IDLE;
              job_ready <= 1'b1;
            end else begin
              ms      <= M_INGEST;
              x_ready <= 1'b1;
              iv      <= '0;
              ic      <= 5'd0;
              cnt     <= ((rem - 16'(cnt)) > 16'(2 * E)) ? (VW+1)'(2 * E) : (VW+1)'(rem - 16'(cnt));
              tiles   <= 11'((12'd1 << lgq) << lgq);
              lr      <= 5'd0;
              lc      <= 5'd0;
            end
          end
        end
        default: ms <= M_IDLE;
      endcase

      // the weight loader: one burst per tile into the shadow registers, one tile ahead of the array
      ld <= '0;
      case (ls)
        L_IDLE: begin
          if ((tiles != 11'd0) & ~sh_full & ~start_pass & (ms != M_IDLE)) begin
            rq_valid <= 1'b1;
            rq_addr  <= 32'(((32'(lr) << lgq) + 32'(lc)) << LGE);
            rq_len   <= 24'(E);
            ls       <= L_REQ;
          end
        end
        L_REQ: begin
          if (rq_valid & rq_ready) begin
            rq_valid <= 1'b0;
            ls       <= L_RX;
            li       <= '0;
            tiles    <= tiles - 11'd1;
            lc       <= (lc == nbm) ? 5'd0 : lc + 5'd1;
            if (lc == nbm) lr <= lr + 5'd1;
          end
        end
        L_RX: begin
          // a beat may land in the shadow registers only when the last swap has passed (wave = 0)
          rd_ready <= (wave <= 16'd1) & ~(rd_take & (li == (LGE+1)'(E - 1)));
          if (rd_take) begin
            ld[li[LGE-1:0]] <= 1'b1;
            li <= li + 1'b1;
            if (li == (LGE+1)'(E - 1)) begin
              sh_full <= 1'b1;
              ls      <= L_IDLE;
            end
          end
        end
        default: ls <= L_IDLE;
      endcase
    end
  end
endmodule

// The activation buffer: 64 E beats (2 E vectors of up to 32 beats) in 1024-word blocks, 64 bits each.
// `q` is every bank's output and `qsel` the bank that was read: the reader selects.
module gemm_xbuf #(parameter int LGE = 2, parameter int LGB = 0) (
  input  logic                   clk,
  input  logic                   we_v, we_r,
  input  logic [LGE+5:0]         waddr,
  input  logic [16*(1<<LGE)-1:0] wdata,
  input  logic                   rd,
  input  logic [LGE+5:0]         raddr,
  output logic [(16<<LGE)*(1<<LGB)-1:0] q,
  output logic [LGB:0]           qsel
);
  localparam int MEMW = 16 << LGE;
  localparam int AW = LGE + 6;
  logic            we;
  logic [9:0]      wa, ra;
  logic [LGB:0]    wb, rb;
  assign we = we_v & we_r;
  assign wa = 10'(waddr);
  assign ra = 10'(raddr);
  if (LGB == 0) begin : g_one
    assign wb = '0;
    assign rb = '0;
  end else begin : g_many
    assign wb = {1'b0, waddr[AW-1:10]};
    assign rb = {1'b0, raddr[AW-1:10]};
  end
  for (genvar b = 0; b < (1 << LGB); b++) begin : g_bank
    logic bw, br;
    assign bw = we & (wb == b);
    assign br = rd & (rb == b) & ~bw;
    for (genvar k = 0; k < MEMW / 64; k++) begin : g_blk
      srambank_256x4x64_6t122 m (.clk(clk), .ADDRESS(bw ? wa : ra), .wd(wdata[64*k +: 64]), .banksel(bw | br),
                                 .read(br), .write(bw), .dataout(q[MEMW*b + 64*k +: 64]));
    end
  end
  always_ff @(posedge clk)
    if (rd) qsel <= rb;
endmodule

// The input skew of the inner-product array: pair t of the activation beat (and the swap tag) is delayed t + 1
// cycles, so that every cell of a row sees its pair one cycle after its left neighbour's. The activation
// correction sum_t x[2t] * x[2t+1] (modulo 2^SW) is formed from every column's first register and leaves
// H + 2 cycles after the beat: the cycle row 0 writes the beat's sum.
module gemm_skewp #(parameter int LGE = 2, parameter int LGB = 0) (
  input  logic                   clk,
  input  logic                   swap,
  input  logic [(16<<LGE)*(1<<LGB)-1:0] q,
  input  logic [LGB:0]           qsel,
  output logic [(1<<(LGE-1))-1:0] swap_o,
  output logic [16*(1<<LGE)-1:0] x_o,
  output logic [32+LGE:0]        cx
);
  localparam int E = 1 << LGE;
  localparam int H = E / 2;
  localparam int MEMW = 16 * E;
  localparam int SW = 33 + LGE;
  localparam int PAD = H - LGE / 2;                 // the delay line behind the tree, >= 1
  logic [MEMW-1:0] x;
  logic [MEMW*((1<<LGB)+1)-1:0] pick;               // the selected bank's beat, as an OR over the banks
  assign pick[MEMW-1:0] = '0;
  for (genvar b = 0; b < (1 << LGB); b++) begin : g_pick
    assign pick[MEMW*(b+1) +: MEMW] = pick[MEMW*b +: MEMW] | ((qsel == b) ? q[MEMW*b +: MEMW] : '0);
  end
  assign x = pick[MEMW*(1<<LGB) +: MEMW];
  logic [SW*H-1:0] pe;
  for (genvar t = 0; t < H; t++) begin : g_col
    logic [33*(t+1)-1:0] d;
    logic [31:0]         p;
    if (t == 0) begin : g_first
      always_ff @(posedge clk) d <= {swap, x[31:0]};
    end else begin : g_rest
      always_ff @(posedge clk) d <= {d[33*t-1:0], swap, x[32*t +: 32]};
    end
    always_ff @(posedge clk) p <= {16'd0, d[15:0]} * {16'd0, d[31:16]};
    assign swap_o[t]        = d[33*t + 32];
    assign x_o[32*t +: 32]  = d[33*t +: 32];
    assign pe[SW*t +: SW]   = {{(SW-32){1'b0}}, p};
  end
  logic [SW-1:0]     cxs;
  logic [SW*PAD-1:0] dl;
  gemm_sum #(.LGE(LGE), .W(SW)) tree (.clk(clk), .d(pe), .q(cxs));
  if (PAD == 1) begin : g_one
    always_ff @(posedge clk) dl <= cxs;
  end else begin : g_line
    always_ff @(posedge clk) dl <= {dl[SW*(PAD-1)-1:0], cxs};
  end
  assign cx = dl[SW*(PAD-1) +: SW];
endmodule

// The weight correction of one tile row (one beat): -sum_t w[2t] * w[2t+1] modulo 2^SW, 1 + LGE/2 cycles.
module gemm_wcorr #(parameter int LGE = 2) (
  input  logic                   clk,
  input  logic [16*(1<<LGE)-1:0] w,
  output logic [32+LGE:0]        ncw
);
  localparam int H = 1 << (LGE - 1);
  localparam int SW = 33 + LGE;
  logic [SW*H-1:0] pe;
  for (genvar t = 0; t < H; t++) begin : g_p
    logic [31:0] core;
    logic signed [32:0] prod;
    logic signed [31:0] p;
    assign core = $unsigned(w[32*t +: 16]) * $unsigned(w[32*t+16 +: 16]);
    assign prod = $signed({1'b0, core})
                - (w[32*t + 15] ? $signed({1'b0, w[32*t+16 +: 16], 16'b0}) : 33'sd0)
                - (w[32*t+16 + 15] ? $signed({1'b0, w[32*t +: 16], 16'b0}) : 33'sd0)
                + ((w[32*t + 15] && w[32*t+16 + 15]) ? 33'sh100000000 : 33'sd0);
    always_ff @(posedge clk) p <= -prod[31:0];
    assign pe[SW*t +: SW] = {{(SW-32){p[31]}}, p};
  end
  gemm_sum #(.LGE(LGE), .W(SW)) tree (.clk(clk), .d(pe), .q(ncw));
endmodule

// The sum of 2^(LGE-1) values modulo 2^W: a tree, four values per register stage, LGE/2 stages.
module gemm_sum #(parameter int LGE = 2, parameter int W = 35) (
  input  logic                        clk,
  input  logic [W*(1<<(LGE-1))-1:0]   d,
  output logic [W-1:0]                q
);
  localparam int H = 1 << (LGE - 1);
  localparam int TS = LGE / 2;
  if (TS == 0) begin : g_wire
    assign q = d[W-1:0];
  end else begin : g_tree
    logic [W*H*TS-1:0] vr;                                 // stage s's outputs in slot s (unused entries are 0)
    logic [W*H*TS-1:0] vi;                                 // stage s's inputs in slot s
    assign vi[W*H-1:0] = d;
    for (genvar s = 1; s < TS; s++) begin : g_in
      assign vi[W*H*s +: W*H] = vr[W*H*(s-1) +: W*H];
    end
    for (genvar s = 0; s < TS; s++) begin : g_st
      localparam int NI = H >> (2 * s);
      localparam int G = (NI >= 4) ? 4 : 2;
      for (genvar k = 0; k < H; k++) begin : g_k
        if (k < NI / G) begin : g_add
          if (G == 4) begin : g_four
            always_ff @(posedge clk)
              vr[W*H*s + W*k +: W] <= (vi[W*H*s + W*(4*k) +: W] + vi[W*H*s + W*(4*k+1) +: W])
                                    + (vi[W*H*s + W*(4*k+2) +: W] + vi[W*H*s + W*(4*k+3) +: W]);
          end else begin : g_two
            always_ff @(posedge clk)
              vr[W*H*s + W*k +: W] <= vi[W*H*s + W*(2*k) +: W] + vi[W*H*s + W*(2*k+1) +: W];
          end
        end else begin : g_zero
          always_ff @(posedge clk) vr[W*H*s + W*k +: W] <= '0;
        end
      end
    end
    assign q = vr[W*H*(TS-1) +: W];
  end
endmodule

// The inner-product array: E rows; activations, their correction, the swap tag and the accumulate control travel
// down the rows.
module gemm_arrayf #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic [(1<<LGE)-1:0] ld,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic [(1<<LGE)-1:0] cld,
  input  logic [32+LGE:0]     cw_d,
  input  logic [(1<<(LGE-1))-1:0] swap,
  input  logic [16*(1<<LGE)-1:0] x,
  input  logic [32+LGE:0]     cx,
  input  logic                a_rd, a_first,
  input  logic [LGE:0]        a_v,
  input  logic                r_rd,
  input  logic [LGE:0]        r_v,
  input  logic [15:0]         mul,
  input  logic [5:0]          shift,
  input  logic [15:0]         zp, lo, hi,
  output logic [16*(1<<LGE)-1:0] y
);
  localparam int E = 1 << LGE;
  localparam int H = E / 2;
  localparam int MEMW = 16 * E;
  localparam int SW = 33 + LGE;
  logic [H*(E+1)-1:0]     sw;
  logic [MEMW*(E+1)-1:0]  xx;
  logic [SW*(E+1)-1:0]    cc;
  logic [E:0]             ard, afi;
  logic [(LGE+1)*(E+1)-1:0] av;
  assign sw[H-1:0]    = swap;
  assign xx[MEMW-1:0] = x;
  assign cc[SW-1:0]   = cx;
  assign ard[0]       = a_rd;
  assign afi[0]       = a_first;
  assign av[LGE:0]    = a_v;
  for (genvar i = 0; i < E; i++) begin : g_row
    gemm_rowf #(.LGE(LGE)) u (
      .clk(clk), .ld(ld[i]), .w_d(w_d), .cld(cld[i]), .cw_d(cw_d), .swap_in(sw[H*i +: H]),
      .x_in(xx[MEMW*i +: MEMW]), .cx_in(cc[SW*i +: SW]),
      .a_rd(ard[i]), .a_first(afi[i]), .a_v(av[(LGE+1)*i +: LGE+1]), .r_rd(r_rd), .r_v(r_v),
      .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi),
      .swap_out(sw[H*(i+1) +: H]), .x_out(xx[MEMW*(i+1) +: MEMW]), .cx_out(cc[SW*(i+1) +: SW]),
      .a_rd_o(ard[i+1]), .a_first_o(afi[i+1]), .a_v_o(av[(LGE+1)*(i+1) +: LGE+1]),
      .y(y[16*i +: 16]));
  end
endmodule

// One row of the inner-product array: E/2 cells, the row's weight correction (shadow and active, the active one
// starts the sum chain), the row's accumulator memory (two blocks, even and odd vectors) and its output stage.
// The activation correction arrives in the cycle the chain's sum is written, and goes on to the next row.
module gemm_rowf #(parameter int LGE = 2) (
  input  logic                clk,
  input  logic                ld,
  input  logic [16*(1<<LGE)-1:0] w_d,
  input  logic                cld,
  input  logic [32+LGE:0]     cw_d,
  input  logic [(1<<(LGE-1))-1:0] swap_in,
  input  logic [16*(1<<LGE)-1:0] x_in,
  input  logic [32+LGE:0]     cx_in,
  input  logic                a_rd, a_first,
  input  logic [LGE:0]        a_v,
  input  logic                r_rd,
  input  logic [LGE:0]        r_v,
  input  logic [15:0]         mul,
  input  logic [5:0]          shift,
  input  logic [15:0]         zp, lo, hi,
  output logic [(1<<(LGE-1))-1:0] swap_out,
  output logic [16*(1<<LGE)-1:0] x_out,
  output logic [32+LGE:0]     cx_out,
  output logic                a_rd_o, a_first_o,
  output logic [LGE:0]        a_v_o,
  output logic [15:0]         y
);
  localparam int E = 1 << LGE;
  localparam int H = E / 2;
  localparam int SW = 33 + LGE;
  logic [SW-1:0]       cw_sh, cw_act;
  logic [SW*(H+1)-1:0] s;
  assign s[SW-1:0] = cw_act;
  for (genvar t = 0; t < H; t++) begin : g_cell
    gemm_cellf #(.SW(SW)) u (.clk(clk), .ld(ld), .w_d(w_d[32*t +: 32]), .swap_in(swap_in[t]),
                             .x_in(x_in[32*t +: 32]), .s_in(s[SW*t +: SW]), .swap_out(swap_out[t]),
                             .x_out(x_out[32*t +: 32]), .s_out(s[SW*(t+1) +: SW]));
  end

  logic        r_sel;
  logic [SW-1:0] ip;                                  // the slice's inner product modulo 2^SW
  logic [47:0] d0, d1, wd, add_a, add_b, csa_sum;
  logic [12:0] csa_c;
  logic        rd0, rd1, wr0, wr1;
  logic [7:0]  ad0, ad1;
  assign ip  = s[SW*H +: SW] - cx_in;
  assign wr0 = a_rd_o & ~a_v_o[0];
  assign wr1 = a_rd_o &  a_v_o[0];
  assign rd0 = (a_rd & ~a_v[0]) | (r_rd & ~r_v[0]);
  assign rd1 = (a_rd &  a_v[0]) | (r_rd &  r_v[0]);
  assign ad0 = wr0 ? 8'(a_v_o[LGE:1]) : a_rd ? 8'(a_v[LGE:1]) : 8'(r_v[LGE:1]);
  assign ad1 = wr1 ? 8'(a_v_o[LGE:1]) : a_rd ? 8'(a_v[LGE:1]) : 8'(r_v[LGE:1]);
  assign add_a = a_first_o ? 48'd0 : (a_v_o[0] ? d1 : d0);
  assign add_b = {{(48-SW){ip[SW-1]}}, ip};
  assign {csa_c[1], csa_sum[3:0]} = add_a[3:0] + add_b[3:0];
  for (genvar g = 1; g < 12; g++) begin : g_csa
    logic [4:0] s0, s1;
    assign s0 = add_a[4*g +: 4] + add_b[4*g +: 4];
    assign s1 = add_a[4*g +: 4] + add_b[4*g +: 4] + 5'd1;
    assign csa_sum[4*g +: 4] = csa_c[g] ? s1[3:0] : s0[3:0];
    assign csa_c[g+1] = csa_c[g] ? s1[4] : s0[4];
  end
  assign wd = csa_sum;
  srambank_64x4x48_6t122 m0 (.clk(clk), .ADDRESS(ad0), .wd(wd), .banksel(rd0 | wr0), .read(rd0 & ~wr0),
                             .write(wr0), .dataout(d0));
  srambank_64x4x48_6t122 m1 (.clk(clk), .ADDRESS(ad1), .wd(wd), .banksel(rd1 | wr1), .read(rd1 & ~wr1),
                             .write(wr1), .dataout(d1));
  always_ff @(posedge clk) begin
    if (cld) cw_sh <= cw_d;
    if (swap_out[0]) cw_act <= cw_sh;
    cx_out    <= cx_in;
    a_rd_o    <= a_rd;
    a_first_o <= a_first;
    a_v_o     <= a_v;
    if (r_rd) r_sel <= r_v[0];
  end
  gemm_scale sc (.clk(clk), .d0(d0), .d1(d1), .sel(r_sel), .mul(mul), .shift(shift), .zp(zp), .lo(lo), .hi(hi),
                 .y(y));
endmodule

// One cell of the inner-product array: (w0 + x1) * (w1 + x0) added to the row's sum chain; (w0, w1) is a pair of
// weights, double-buffered as in par (`ld` loads the shadow, the tag `swap_in` moves it into the active register),
// (x0, x1) the pair of activations. The pre-adders are registered; the product and the chain add share a cycle.
module gemm_cellf #(parameter int SW = 35) (
  input  logic          clk,
  input  logic          ld,
  input  logic [31:0]   w_d,
  input  logic          swap_in,
  input  logic [31:0]   x_in,
  input  logic [SW-1:0] s_in,
  output logic          swap_out,
  output logic [31:0]   x_out,
  output logic [SW-1:0] s_out
);
  logic [31:0]        w_sh, w_act;
  logic signed [17:0] a, b;
  logic [35:0]        core;
  logic signed [47:0] p;
  // Signed product from one unsigned 18x18 core plus two sign rows and the corner term.
  assign core = $unsigned(a) * $unsigned(b);
  assign p = $signed({12'b0, core})
           - (a[17] ? $signed({12'b0, b, 18'b0}) : 48'sd0)
           - (b[17] ? $signed({12'b0, a, 18'b0}) : 48'sd0)
           + ((a[17] && b[17]) ? 48'sh001000000000 : 48'sd0);
  always_ff @(posedge clk) begin
    if (ld) w_sh <= w_d;
    if (swap_in) w_act <= w_sh;
    swap_out <= swap_in;
    x_out    <= x_in;
    a        <= $signed({{2{w_act[15]}}, w_act[15:0]})  + $signed({2'b00, x_in[31:16]});
    b        <= $signed({{2{w_act[31]}}, w_act[31:16]}) + $signed({2'b00, x_in[15:0]});
    s_out    <= s_in + p[SW-1:0];
  end
endmodule

// The output stage on one sum, five register stages, none longer than the cell's multiply-accumulate:
//   1  the sum times M, in two halves (the exact sum fits 44 bits: at most 4096 products below 2^31)
//   2  the product
//   3  the product, doubled, shifted right by s: its low 20 bits, and whether it fits them
//   4  rounded (half up) and the zero point added
//   5  clamped
// floor((p + 2^(s-1)) / 2^s) = ((2p >> s) + 1) >> 1 for every s >= 0 (for s = 0: (2p + 1) >> 1 = p).
module gemm_scale (
  input  logic        clk,
  input  logic [47:0] d0, d1,
  input  logic        sel,
  input  logic [15:0] mul,
  input  logic [5:0]  shift,
  input  logic [15:0] zp, lo, hi,
  output logic [15:0] y
);
  logic signed [43:0] a;
  logic signed [38:0] ph;
  logic        [37:0] pl;
  logic signed [59:0] p;
  logic signed [60:0] q;
  logic signed [19:0] q20;
  logic signed [20:0] r, t;
  logic               fit, neg, fit_t, neg_t;
  assign a = sel ? d1[43:0] : d0[43:0];
  assign q = $signed({p, 1'b0}) >>> shift;
  assign r = ($signed({q20[19], q20}) + 21'sd1) >>> 1;
  always_ff @(posedge clk) begin
    ph    <= $signed(a[43:22]) * $signed({1'b0, mul});
    pl    <= a[21:0] * mul;
    p     <= $signed({ph, 22'd0}) + $signed({1'b0, pl});
    q20   <= q[19:0];
    fit   <= (q[60:19] == {42{q[19]}});
    neg   <= q[60];
    t     <= r + $signed({5'd0, zp});
    fit_t <= fit;
    neg_t <= neg;
    if (~fit_t)                         y <= neg_t ? lo : hi;
    else if (t < $signed({5'd0, lo})) y <= lo;
    else if (t > $signed({5'd0, hi})) y <= hi;
    else                                y <= t[15:0];
  end
endmodule

// The result FIFO: 2^LGD entries and an output register.
module gemm_fifo #(parameter int W = 8, parameter int LGD = 3) (
  input  logic         clk, rst,
  input  logic         push,
  input  logic [W-1:0] din,
  input  logic         pop_ready,
  output logic         valid,
  output logic [W-1:0] dout
);
  localparam int D = 1 << LGD;
  logic [W*D-1:0]     mem;
  logic [W*(D+1)-1:0] pick;                           // the entry at the read pointer, as an OR over the entries
  logic [LGD-1:0] wp, rp;
  logic [LGD:0]   cnt;
  logic           take, direct;
  assign take   = ~valid | pop_ready;                 // the output register is free after this cycle
  assign direct = take & (cnt == '0);                 // a pushed beat goes straight to it
  assign pick[W-1:0] = '0;
  for (genvar i = 0; i < D; i++) begin : g_entry
    always_ff @(posedge clk)
      if (push & ~direct & (wp == i)) mem[W*i +: W] <= din;
    assign pick[W*(i+1) +: W] = pick[W*i +: W] | ((rp == i) ? mem[W*i +: W] : '0);
  end
  always_ff @(posedge clk) begin
    if (take) begin
      if (cnt != '0)  dout <= pick[W*D +: W];
      else if (push)  dout <= din;
    end
    if (rst) begin
      valid <= 1'b0;
      wp    <= '0;
      rp    <= '0;
      cnt   <= '0;
    end else begin
      if (take) valid <= (cnt != '0) | push;
      if (push & ~direct) wp <= wp + 1'b1;
      if (take & (cnt != '0)) rp <= rp + 1'b1;
      cnt <= cnt + {{LGD{1'b0}}, (push & ~direct)} - {{LGD{1'b0}}, (take & (cnt != '0))};
    end
  end
endmodule
